package io.mavsdk.kotlin.plugins.mavlink_direct

import io.mavsdk.kotlin.System
import kotlinx.coroutines.channels.awaitClose
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.callbackFlow

class MavlinkDirect internal constructor(private val native: MavlinkDirectNative) : AutoCloseable {
    private var closed = false

    enum class Result(val value: Int) {
        UNKNOWN(0),
        SUCCESS(1),
        ERROR(2),
        INVALID_MESSAGE(3),
        INVALID_FIELD(4),
        CONNECTION_ERROR(5),
        NO_SYSTEM(6),
        TIMEOUT(7);

        companion object {
            fun fromValue(value: Int): Result = entries.find { it.value == value } ?: UNKNOWN
        }
    }

    data class MavlinkMessage(
        val messageName: String,
        val systemId: Int,
        val componentId: Int,
        val targetSystemId: Int,
        val targetComponentId: Int,
        val fieldsJson: String,
    )

    fun sendMessage(message: MavlinkMessage): Result = Result.fromValue(native.sendMessage(message))

    fun subscribeMessage(messageName: String): Flow<MavlinkMessage> = callbackFlow {
        val subscriptionHandle = native.subscribeMessage(messageName) { value -> trySend(value) }
        awaitClose { native.unsubscribeMessage(subscriptionHandle) }
    }

    fun loadCustomXml(xmlContent: String): Result =
        Result.fromValue(native.loadCustomXml(xmlContent))

    override fun close() {
        if (closed) return
        closed = true
        native.destroy()
    }

    class MavlinkDirectException(val result: Result, message: String) : Exception(message)

    companion object {
        fun create(system: System): MavlinkDirect =
            MavlinkDirect(createMavlinkDirectNative(system.getHandle())).also {
                system.registerPlugin(it)
            }
    }
}

internal interface MavlinkDirectNative {
    fun sendMessage(message: MavlinkDirect.MavlinkMessage): Int

    fun subscribeMessage(
        messageName: String,
        callback: (MavlinkDirect.MavlinkMessage) -> Unit,
    ): Long

    fun unsubscribeMessage(subscriptionHandle: Long)

    fun loadCustomXml(xmlContent: String): Int

    fun destroy()
}

internal expect fun createMavlinkDirectNative(systemHandle: Long): MavlinkDirectNative
